import sys

def remove_duplicates_brute(nums):
    seen = set()
    res = []
    for x in nums:
        if x not in seen:
            seen.add(x)
            res.append(x)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    res = remove_duplicates_brute(nums)
    print(len(res))
    if res:
        print(' '.join(map(str, res)))

import sys

def remove_duplicates_opt(nums):
    if not nums:
        return 0
    slow = 1
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow - 1]:
            nums[slow] = nums[fast]
            slow += 1
    return slow, nums[:slow]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    k, res = remove_duplicates_opt(nums)
    print(k)
    if res:
        print(' '.join(map(str, res)))

import sys

def remove_duplicates_general(nums, k=1):
    # 允许每个值最多出现 k 次（k=1 即本题）
    slow = 0
    for x in nums:
        if slow < k or x != nums[slow - k]:
            nums[slow] = x
            slow += 1
    return slow, nums[:slow]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    k, res = remove_duplicates_general(nums, k=1)
    print(k)
    if res:
        print(' '.join(map(str, res)))
